from z3 import *

def parse_time(s):
    s = s.strip()
    ampm = s[-2:].upper()
    h, m = s[:-2].split(':')
    h = int(h)
    m = int(m)
    if ampm == 'PM' and h != 12:
        h += 12
    elif ampm == 'AM' and h == 12:
        h = 0
    return h * 60 + m

def format_time(x):
    x = int(x) % 1440
    h = x // 60
    m = x % 60
    suffix = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

def eval_bool(m, expr):
    v = m.eval(expr, model_completion=True)
    return v.as_bool() if hasattr(v, "as_bool") else bool(v)

def eval_int(m, expr):
    v = m.eval(expr, model_completion=True)
    return v.as_long() if hasattr(v, "as_long") else int(v)

def main():
    locs = ["L1", "L2", "L3", "L4", "L5", "L6"]
    specs = [
        ("Person1", "L2", "T5", "T9", "D3"),
        ("Person2", "L3", "T6", "T7", "D5"),
        ("Person3", "L4", "T3", "T1", "D4"),
        ("Person4", "L5", "T8", "T10", "D1"),
        ("Person5", "L6", "T4", "T2", "D2"),
    ]

    loc_names = [VALUES[l] for l in locs]
    loc_idx = {l: i for i, l in enumerate(locs)}
    start_min = parse_time(VALUES["T11"])

    friends = []
    for person_ph, loc_ph, start_ph, end_ph, dur_ph in specs:
        friends.append((
            VALUES[person_ph],
            loc_idx[loc_ph],
            parse_time(VALUES[start_ph]),
            parse_time(VALUES[end_ph]),
            int(VALUES[dur_ph]),
        ))

    n = len(friends)

    def get_travel(a_ph, b_ph):
        if a_ph == b_ph:
            return 0
        try:
            return int(TRAVEL[a_ph][b_ph])
        except KeyError:
            return int(TRAVEL[VALUES[a_ph]][VALUES[b_ph]])

    travel = [[0] * 6 for _ in range(6)]
    for a in range(6):
        for b in range(6):
            if a != b:
                travel[a][b] = get_travel(locs[a], locs[b])

    meet = [Bool(f"meet_{p}") for p in range(n)]
    friend = [Int(f"friend_{p}") for p in range(n)]
    loc = [Int(f"loc_{p}") for p in range(n)]
    travel_p = [Int(f"travel_{p}") for p in range(n)]
    start = [Int(f"start_{p}") for p in range(n)]
    end = [Int(f"end_{p}") for p in range(n)]
    at_time = [Int(f"at_time_{p}") for p in range(n + 1)]
    at_loc = [Int(f"at_loc_{p}") for p in range(n + 1)]

    base = [at_time[0] == start_min, at_loc[0] == 0]

    for p in range(n + 1):
        base += [
            at_time[p] >= 0,
            at_time[p] <= 1440,
            at_loc[p] >= 0,
            at_loc[p] <= 5,
        ]

    for p in range(n):
        base += [
            friend[p] >= 0,
            friend[p] <= n - 1,
            loc[p] >= 0,
            loc[p] <= 5,
            travel_p[p] >= 0,
            start[p] >= 0,
            start[p] <= 1440,
            end[p] >= 0,
            end[p] <= 1440,
            at_time[p + 1] >= at_time[p],
        ]

        for a in range(6):
            for b in range(6):
                base.append(Implies(And(at_loc[p] == a, loc[p] == b), travel_p[p] == travel[a][b]))

        for i in range(n):
            _, li, ws, we, d = friends[i]
            base.append(Implies(And(meet[p], friend[p] == i), And(
                loc[p] == li,
                start[p] >= at_time[p] + travel_p[p],
                start[p] >= ws,
                end[p] == start[p] + d,
                end[p] <= we,
            )))

        base.append(at_time[p + 1] == If(meet[p], end[p], at_time[p]))
        base.append(at_loc[p + 1] == If(meet[p], loc[p], at_loc[p]))

    for i in range(n):
        base.append(Sum(*[If(And(meet[p], friend[p] == i), 1, 0) for p in range(n)]) <= 1)

    count = Int("count")
    base.append(count == Sum(*[If(meet[p], 1, 0) for p in range(n)]))

    max_count = 0
    fallback_model = None
    for k in range(n, -1, -1):
        s = Solver()
        for c in base:
            s.add(c)
        s.add(count == k)
        if s.check() == sat:
            max_count = k
            fallback_model = s.model()
            break

    if fallback_model is None:
        print([])
        return

    opt = Optimize()
    for c in base:
        opt.add(c)
    opt.add(count == max_count)
    opt.minimize(at_time[n])

    if opt.check() == sat:
        opt_model = opt.model()
        m = opt_model if opt_model is not None else fallback_model
    else:
        m = fallback_model

    statements = [f"You start at {loc_names[0]} at {format_time(start_min)}."]

    for p in range(n):
        if not eval_bool(m, meet[p]):
            continue
        cur_time = eval_int(m, at_time[p])
        cur_loc = eval_int(m, at_loc[p])
        fi = eval_int(m, friend[p])
        st = eval_int(m, start[p])
        en = eval_int(m, end[p])
        me_loc = friends[fi][1]
        tr = travel[cur_loc][me_loc]
        arrive = cur_time + tr
        if me_loc != cur_loc:
            statements.append(f"You travel to {loc_names[me_loc]} in {tr} minutes and arrive at {format_time(arrive)}.")
        if arrive < st:
            statements.append(f"You wait until {format_time(st)}.")
        dur = en - st
        statements.append(f"You meet {friends[fi][0]} for {dur} minutes from {format_time(st)} to {format_time(en)}.")

    print(statements)

main()

from z3 import *

def parse_time(t):
    t = str(t).strip().upper()
    if t.endswith("AM") or t.endswith("PM"):
        suffix = t[-2:]
        body = t[:-2]
    else:
        suffix = "AM"
        body = t
    body = body.strip()
    parts = body.split(":")
    h = int(parts[0].strip())
    m = int(parts[1].strip()) if len(parts) > 1 else 0
    if suffix == "PM":
        if h != 12:
            h += 12
    else:
        if h == 12:
            h = 0
    return h * 60 + m

def format_time(minutes):
    minutes = int(minutes) % 1440
    h24 = minutes // 60
    m = minutes % 60
    suffix = "AM" if h24 < 12 else "PM"
    h12 = h24 % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

def travel_minutes(a, b):
    if a == b:
        return 0
    return int(TRAVEL[a][b])

friends = [
    ("Person1", "L2", "T1", "T6", "D1"),
    ("Person2", "L3", "T4", "T2", "D2"),
    ("Person3", "L4", "T7", "T3", "D1"),
]
start_loc = "L1"
start_time = "T5"
n = len(friends)
max_slots = n

friend_data = []
for person_ph, loc_ph, ws_ph, we_ph, dur_ph in friends:
    ws = parse_time(VALUES[ws_ph])
    we = parse_time(VALUES[we_ph])
    if ws > we:
        we += 1440
    dur = int(VALUES[dur_ph])
    friend_data.append((person_ph, loc_ph, ws, we, dur))

solver = Optimize()
count = Int("count")
solver.add(count >= 0, count <= max_slots)

person_at = [Int(f"person_at_{s}") for s in range(max_slots)]
start_at = [Int(f"start_at_{s}") for s in range(max_slots)]
end_at = [Int(f"end_at_{s}") for s in range(max_slots)]

for s in range(max_slots):
    solver.add(person_at[s] >= 0, person_at[s] <= n - 1)
    solver.add(start_at[s] >= 0, start_at[s] <= 2880)
    solver.add(end_at[s] >= 0, end_at[s] <= 2880)

start0 = parse_time(VALUES[start_time])

for s in range(max_slots):
    used = count > s
    for i, (_, loc_ph, ws, we, dur) in enumerate(friend_data):
        solver.add(
            Implies(
                And(used, person_at[s] == i),
                And(
                    start_at[s] >= ws,
                    start_at[s] + dur <= we,
                    end_at[s] == start_at[s] + dur
                )
            )
        )

for s in range(max_slots):
    for t in range(s + 1, max_slots):
        solver.add(Implies(count > t, person_at[s] != person_at[t]))

for i, (_, loc_ph, _, _, _) in enumerate(friend_data):
    solver.add(
        Implies(
            And(count > 0, person_at[0] == i),
            start_at[0] >= start0 + travel_minutes(start_loc, loc_ph)
        )
    )

for s in range(1, max_slots):
    for i in range(n):
        loc_i = friend_data[i][1]
        for j in range(n):
            loc_j = friend_data[j][1]
            solver.add(
                Implies(
                    And(count > s, person_at[s - 1] == i, person_at[s] == j),
                    start_at[s] >= end_at[s - 1] + travel_minutes(loc_i, loc_j)
                )
            )

last_end = Int("last_end")
solver.add(last_end >= 0)
for s in range(max_slots):
    solver.add(last_end >= If(count > s, end_at[s], 0))

solver.maximize(count)
solver.minimize(last_end)
for s in range(max_slots):
    solver.minimize(If(count > s, start_at[s], 0))
    solver.minimize(If(count > s, end_at[s], 0))

if solver.check() == sat:
    m = solver.model()

    def model_int(expr):
        return m.eval(expr, model_completion=True).as_long()

    count_val = model_int(count)
    itinerary = []
    current_loc = start_loc
    current_time = start0

    itinerary.append(f"You start at {VALUES[start_loc]} at {format_time(current_time)}.")

    for s in range(count_val):
        i = model_int(person_at[s])
        person_ph, loc_ph, _, _, dur = friend_data[i]
        loc_actual = VALUES[loc_ph]

        travel = travel_minutes(current_loc, loc_ph)
        arrive = current_time + travel

        if travel > 0 or current_loc != loc_ph:
            itinerary.append(
                f"You travel to {loc_actual} in {travel} minutes and arrive at {format_time(arrive)}."
            )

        current_time = arrive
        current_loc = loc_ph

        meeting_start = model_int(start_at[s])
        meeting_end = model_int(end_at[s])

        if current_time < meeting_start:
            itinerary.append(f"You wait until {format_time(meeting_start)}.")
            current_time = meeting_start

        duration = meeting_end - current_time
        person_actual = VALUES[person_ph]

        itinerary.append(
            f"You meet {person_actual} for {duration} minutes from {format_time(current_time)} to {format_time(meeting_end)}."
        )

        current_time = meeting_end

    print(itinerary)
else:
    print([])

from z3 import *

def parse_time(t):
    t = str(t).strip().upper()
    if t.endswith("AM"):
        is_am = True
        t = t[:-2]
    elif t.endswith("PM"):
        is_am = False
        t = t[:-2]
    else:
        is_am = True

    parts = t.split(":")
    h = int(parts[0])
    m = int(parts[1]) if len(parts) > 1 else 0

    if is_am:
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12

    return h * 60 + m

def fmt_time(t):
    t = int(t)
    h = t // 60
    m = t % 60
    ampm = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{ampm}"

friends = [
    ("Person1", "L2", "T5", "T9", "D3"),
    ("Person2", "L3", "T4", "T8", "D4"),
    ("Person3", "L4", "T7", "T3", "D1"),
    ("Person4", "L5", "T11", "T10", "D5"),
    ("Person5", "L6", "T6", "T1", "D2"),
]

start_loc = "L1"
arrival = parse_time(VALUES["T2"])

win_start = [parse_time(VALUES[f[2]]) for f in friends]
win_end = [parse_time(VALUES[f[3]]) for f in friends]
dur = [int(VALUES[f[4]]) for f in friends]
friend_loc = [f[1] for f in friends]

travel_start = [int(TRAVEL[start_loc][loc]) for loc in friend_loc]
travel = [[0] * 5 for _ in range(5)]
for i in range(5):
    for j in range(5):
        if i != j:
            travel[i][j] = int(TRAVEL[friend_loc[i]][friend_loc[j]])

opt = Optimize()
opt.set("timeout", 10000)

k = Int("k")
at = [Int(f"at_{p}") for p in range(5)]
s = [Int(f"s_{p}") for p in range(5)]
e = [Int(f"e_{p}") for p in range(5)]
last_end = Int("last_end")

opt.add(k >= 0, k <= 5)

for p in range(5):
    opt.add(at[p] >= -1, at[p] <= 4)
    opt.add(Implies(at[p] != -1, p < k))
    opt.add(Implies(at[p] == -1, p >= k))
    opt.add(Implies(at[p] == -1, And(s[p] == 0, e[p] == 0)))
    opt.add(s[p] >= 0, e[p] >= 0)

for i in range(5):
    for p in range(5):
        for q in range(p + 1, 5):
            opt.add(Not(And(at[p] == i, at[q] == i)))

for p in range(5):
    for i in range(5):
        opt.add(Implies(
            at[p] == i,
            And(
                s[p] >= win_start[i],
                e[p] == s[p] + dur[i],
                e[p] <= win_end[i]
            )
        ))

for i in range(5):
    opt.add(Implies(at[0] == i, s[0] >= arrival + travel_start[i]))

for p in range(1, 5):
    for a in range(5):
        for b in range(5):
            opt.add(Implies(
                And(at[p - 1] == a, at[p] == b),
                s[p] >= e[p - 1] + travel[a][b]
            ))

opt.add(Implies(k == 0, last_end == arrival))
for p in range(5):
    opt.add(Implies(k == p + 1, last_end == e[p]))

opt.maximize(100000000 * k - 10000 * last_end - sum(s))

res = opt.check()
seq = None

if res == sat:
