    k_val = m.eval(k, model_completion=True).as_long()
    candidate = [m.eval(at[p], model_completion=True).as_long() for p in range(k_val)]
    if all(0 <= idx <= 4 for idx in candidate) and len(set(candidate)) == len(candidate):
