def greedy_times(sequence):
    t = arrival
    loc = start_loc
    out = []
    for idx in sequence:
        if loc == friend_loc[idx]:
            tt = 0
        else:
            tt = int(TRAVEL[loc][friend_loc[idx]])
        t += tt
        ms = max(t, win_start[idx])
        me = ms + dur[idx]
        if me > win_end[idx]:
            return None
        out.append((idx, ms, me))
        t = me
        loc = friend_loc[idx]
    return out

if seq is None:
    def generate_permutations(items, k):
        if k == 0:
            yield ()
        else:
            for i, item in enumerate(items):
                for rest in generate_permutations(items[:i] + items[i + 1:], k - 1):
                    yield (item,) + rest

    best_seq = None
    best_key = None
    for length in range(5, -1, -1):
        for cand in generate_permutations(list(range(5)), length):
            times = greedy_times(cand)
            if times is None:
                continue
            finish = times[-1][2] if times else arrival
            sum_start = sum(x[1] for x in times)
            key = (finish, sum_start, cand)
            if best_key is None or key < best_key:
                best_key = key
                best_seq = cand
        if best_seq is not None:
            break
    seq = best_seq if best_seq is not None else []

times = greedy_times(seq)
if times is None:
