    if loc != current_loc:
        tt = int(TRAVEL[current_loc][loc])
        arrive = current_time + tt
        statements.append(
            f"You travel to {VALUES.get(loc, loc)} in {tt} minutes and arrive at {fmt_time(arrive)}."
        )
        current_time = arrive

    if ms > current_time:
        statements.append(f"You wait until {fmt_time(ms)}.")
        current_time = ms

    person = VALUES.get(f"Person{idx + 1}", f"Person{idx + 1}")
    statements.append(
        f"You meet {person} for {dur[idx]} minutes from {fmt_time(ms)} to {fmt_time(me)}."
    )

    current_time = me
    current_loc = loc

print(statements)

from z3 import *

def time_to_minutes(t):
    t = str(t).strip().replace(" ", "")
    ampm = t[-2:].upper()
    parts = t[:-2].split(":")
    h = int(parts[0])
    m = int(parts[1])
    if ampm == "PM":
        if h != 12:
            h += 12
    else:
        if h == 12:
            h = 0
    return h * 60 + m

def minutes_to_time(m):
    m = int(m) % 1440
    if m == 0:
        return "12:00AM"
    h = m // 60
    mm = m % 60
    if h < 12:
        return f"{h}:{mm:02d}AM"
    if h == 12:
        return f"12:{mm:02d}PM"
    return f"{h - 12}:{mm:02d}PM"

start_loc = "L1"
start_time = "T5"

friends = [
    ("Person1", "L2", "T4", "T3", "D2"),
    ("Person2", "L3", "T5", "T3", "D3"),
    ("Person3", "L4", "T1", "T2", "D1"),
]

def travel_minutes(a, b):
    if a == b:
        return 0
    return int(TRAVEL[a][b])

start_min = time_to_minutes(VALUES[start_time])
n = len(friends)

p = [Int(f"p{i}") for i in range(n)]
s = [Int(f"s{i}") for i in range(n)]
e = [Int(f"e{i}") for i in range(n)]
meet = [Bool(f"meet{i}") for i in range(n)]

opt = Optimize()

for i, (person, loc, ws, we, dur) in enumerate(friends):
    ws_min = time_to_minutes(VALUES[ws])
    we_min = time_to_minutes(VALUES[we])
    if we_min <= ws_min:
        we_min += 1440
    d = int(VALUES[dur])

    opt.add(p[i] >= -1, p[i] <= n)
    opt.add(Implies(meet[i], p[i] >= 0))
    opt.add(Implies(Not(meet[i]), p[i] == -1))

    opt.add(s[i] >= 0, e[i] <= 1440, s[i] <= e[i])
    opt.add(Implies(meet[i], And(s[i] >= ws_min, e[i] <= we_min, e[i] - s[i] >= d)))

for i in range(n):
    for j in range(i + 1, n):
        opt.add(Implies(And(meet[i], meet[j]), p[i] != p[j]))

for i in range(n):
    for j in range(n):
        if i == j:
            continue
        immediate = And(meet[i], meet[j], p[i] < p[j])
        for k in range(n):
            if k == i or k == j:
                continue
            immediate = And(immediate, Or(Not(meet[k]), p[i] >= p[k], p[j] <= p[k]))
        opt.add(Implies(immediate, s[j] >= e[i] + travel_minutes(friends[i][1], friends[j][1])))

for i in range(n):
    first = meet[i]
    for j in range(n):
        if i == j:
            continue
        first = And(first, Or(Not(meet[j]), p[i] < p[j]))
    opt.add(Implies(first, s[i] >= start_min + travel_minutes(start_loc, friends[i][1])))

count = 0
for i in range(n):
    count += If(meet[i], 1, 0)

last_end = Int("last_end")
opt.add(last_end >= 0)
for i in range(n):
    opt.add(Implies(meet[i], last_end >= e[i]))

sum_start = 0
sum_end = 0
for i in range(n):
    sum_start += If(meet[i], s[i], 0)
    sum_end += If(meet[i], e[i], 0)

opt.maximize(count)
opt.minimize(last_end)
opt.minimize(sum_start)
opt.minimize(sum_end)

if opt.check() == sat:
    m = opt.model()
    met = []
    for i in range(n):
        if m[meet[i]].is_true():
            met.append((m[p[i]].as_long(), i))
    met.sort()

    statements = [f"You start at {VALUES[start_loc]} at {minutes_to_time(start_min)}."]
    prev_loc = start_loc
    current = start_min

    for _, i in met:
        person_ph, loc_ph, _, _, _ = friends[i]
        travel = travel_minutes(prev_loc, loc_ph)
        arrival = current + travel

        if VALUES[prev_loc] != VALUES[loc_ph] or travel > 0:
            statements.append(
                f"You travel to {VALUES[loc_ph]} in {travel} minutes and arrive at {minutes_to_time(arrival)}."
            )

        current = arrival
        s_i = m[s[i]].as_long()
        e_i = m[e[i]].as_long()

        if current < s_i:
            statements.append(f"You wait until {minutes_to_time(s_i)}.")
            current = s_i

        statements.append(
            f"You meet {VALUES[person_ph]} from {minutes_to_time(s_i)} to {minutes_to_time(e_i)}."
        )

        current = e_i
        prev_loc = loc_ph

    print(statements)
else:
    print([f"You start at {VALUES[start_loc]} at {minutes_to_time(start_min)}."])

from z3 import *

def parse_time(s):
    s = s.strip().upper()
    if s.endswith("AM"):
        ampm = "AM"
        s = s[:-2]
    elif s.endswith("PM"):
        ampm = "PM"
        s = s[:-2]
    else:
        raise ValueError(s)

    h, m = map(int, s.split(":"))
    if ampm == "AM":
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return h * 60 + m

def format_time(minutes):
    minutes = int(minutes) % (24 * 60)
    h = minutes // 60
    m = minutes % 60

    if h == 0:
        h = 12
        ampm = "AM"
    elif h < 12:
        ampm = "AM"
    elif h == 12:
        ampm = "PM"
    else:
        h -= 12
        ampm = "PM"

    return f"{h}:{m:02d}{ampm}"

friends = [
    ("Person1", "L2", "T5", "T6", "D2"),
    ("Person2", "L3", "T1", "T2", "D1"),
    ("Person3", "L4", "T4", "T2", "D3"),
]

