def parse_time(t):
    t = str(t).strip().replace(' ', '').upper()
    ampm = t[-2:]
    rest = t[:-2]
    parts = rest.split(':')
    h = int(parts[0])
    m = int(parts[1]) if len(parts) > 1 else 0
    if ampm == 'AM':
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12
    return h * 60 + m

def format_time(minutes):
    minutes = int(minutes) % 1440
    h = minutes // 60
    m = minutes % 60
    if h == 0:
        h12 = 12
        ampm = 'AM'
    elif h < 12:
        h12 = h
        ampm = 'AM'
    elif h == 12:
        h12 = 12
        ampm = 'PM'
    else:
        h12 = h - 12
        ampm = 'PM'
    return f"{h12}:{m:02d}{ampm}"

