        hms = s[:-2]
    else:
        suffix = "AM"
        hms = s
    hour, minute = map(int, hms.split(":"))
    if suffix == "AM":
        if hour == 12:
            hour = 0
    else:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

def fmt_time(m):
    m = int(m)
    if m == 1440:
        m = 0
    hour24 = m // 60
    minute = m % 60
    suffix = "AM" if hour24 < 12 else "PM"
    hour12 = hour24 % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{suffix}"

