def to_minutes(t):
    t = str(t).strip().upper()
    if t.endswith("AM") or t.endswith("PM"):
        ampm = t[-2:]
        hm = t[:-2]
    else:
        ampm = "AM"
        hm = t

    h, m = hm.split(":")
    h = int(h)
    m = int(m)

    if ampm == "AM":
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12

    return h * 60 + m


def to_time_str(minutes):
    minutes = int(minutes) % 1440
    period = "AM" if minutes < 720 else "PM"
    h = (minutes // 60) % 12
    if h == 0:
        h = 12
    m = minutes % 60
    return f"{h}:{m:02d}{period}"


