from z3 import *

def parse_time(s):
    s = str(s).strip().replace(' ', '').upper()
    if s.endswith('AM'):
        suffix = 'AM'
        t = s[:-2]
    elif s.endswith('PM'):
        suffix = 'PM'
        t = s[:-2]
    else:
        suffix = 'AM'
        t = s

    parts = t.split(':')
    h = int(parts[0])
    m = int(parts[1]) if len(parts) > 1 else 0

    if suffix == 'AM':
        if h == 12:
            h = 0
    else:
        if h != 12:
            h += 12

    return h * 60 + m


def format_time(minutes):
    minutes = int(minutes) % (24 * 60)
    h = minutes // 60
    m = minutes % 60
    suffix = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"


